namespace af = anira::models;
namespace core = anira::models::core;

using namespace models_test;

TEST(CoreModelSource, ReadsTextFromADirectory) {
    const core::ModelSource source = core::ModelSource::directory(gain_dir());
    EXPECT_TRUE(source.is_directory());
    EXPECT_NE(source.read_text("./LICENSE").find("Apache License"), std::string::npos);
    EXPECT_FALSE(source.find_bytes("LICENSE").has_value());
}

TEST(CoreModelSource, AMissingFileThrows) {
    const core::ModelSource directory = core::ModelSource::directory(gain_dir());
    EXPECT_THROW(directory.read_text("missing.model.json"), af::Error);
    const core::ModelSource bytes = core::ModelSource::bytes({});
    EXPECT_THROW(bytes.read_text("missing.model.json"), af::Error);
}

TEST(CoreModelSource, BytesAreFoundUnderTheNormalPath) {
    const std::array<std::byte, 3> data{std::byte{1}, std::byte{2}, std::byte{3}};
    const core::ModelSource source =
        core::ModelSource::bytes({{.m_path = "onnx/./a/../model.onnx", .m_bytes = data}});
    const auto found = source.find_bytes("onnx/model.onnx");
    ASSERT_TRUE(found.has_value());
    const std::span<const std::byte> bytes = found.value_or(std::span<const std::byte>{});
    EXPECT_EQ(bytes.size(), 3U);
    EXPECT_EQ(bytes.data(), data.data());
}

TEST(CoreModel, LoadsFromADirectoryAndRuns) {
    anira::Context context{anira::ContextConfig{}};
    const core::ModelSource weights = core::ModelSource::directory(gain_dir());
    const anira::ModelConfig model = core::load_model(k_gain_model_json, weights);
    anira::ContractHandle contract = anira::ContractHandle::from_json(k_gain_contract_json);
    expect_runs_on_hard_path(context, model, contract);
}

TEST(CoreModel, LoadsFromBytesAndRuns) {
    const std::vector<std::byte> onnx = read_file(gain_dir() / k_gain_onnx);
    const core::ModelSource weights =
        core::ModelSource::bytes({{.m_path = k_gain_onnx, .m_bytes = onnx}});
    anira::Context context{anira::ContextConfig{}};
    const anira::ModelConfig model = core::load_model(k_gain_model_json, weights);
    anira::ContractHandle contract = anira::ContractHandle::from_json(k_gain_contract_json);
    expect_runs_on_hard_path(context, model, contract);
}

TEST(CoreModel, BytesWithoutTheWeightsThrow) {
    try {
        (void)core::load_model(k_gain_model_json, core::ModelSource::bytes({}));
        FAIL() << "a model without its weights loaded";
    } catch (const af::Error& error) {
        EXPECT_NE(std::string(error.what()).find("simple_gain_network_mono.onnx"),
                  std::string::npos)
            << error.what();
    }
}

// The check of weights against the description is anira's: a description that does not fit the
// model file is refused at prepare, naming the tensor.
TEST(CoreModel, AniraRefusesWeightsThatDoNotFitTheDescription) {
    // Two input channels where the file has one (its time axis is dynamic, its channel axis 1).
    std::string text(k_gain_model_json);
    const std::string one_channel = R"(["channel", 1])";
    text.replace(text.find(one_channel), one_channel.size(), R"(["channel", 2])");
    anira::Context context{anira::ContextConfig{}};
    const anira::ModelConfig model =
        core::load_model(text, core::ModelSource::directory(gain_dir()));
    anira::ContractHandle contract = anira::ContractHandle::from_json(k_gain_contract_json);

    anira_status status = ANIRA_OK;
    std::string message;
    EXPECT_EQ(prepare_handler(context, model, contract, status, message), nullptr);
    EXPECT_EQ(status, ANIRA_ERROR_CONFIG) << message;
    EXPECT_NE(message.find("'audio_in'"), std::string::npos) << message;
}
